1	import { redirect } from "next/navigation";
2	import { LoginForm } from "@/components/AuthForms";
3	import { AuthShell } from "@/components/marketing/AuthShell";
4	import { currentUser } from "@/lib/auth";
5	import { safeNext } from "@/lib/safe-next";
6	import { googleOauthConfigured } from "@/lib/google-oauth";
7	
8	/** Friendly copy for the `?error=` codes the Google OAuth routes bounce back. */
9	const GOOGLE_ERRORS: Record<string, string> = {
10	  google_unavailable: "Google sign-in isn't set up on this server yet. Use your email and password.",
11	  google_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
12	  google_cancelled: "Google sign-in was cancelled.",
13	  google_state: "That Google sign-in link expired or didn't match. Please try again.",
14	  google_unverified: "Your Google email isn't verified, so we can't sign you in with it.",
15	  google_error: "Couldn't finish signing in with Google. Please try again.",
16	  account_suspended: "This account is suspended.",
17	};
18	
19	export default async function LoginPage({
20	  searchParams,
21	}: {
22	  searchParams: Promise<{ next?: string; error?: string }>;
23	}) {
24	  // Where the visitor was heading before the login wall. Public CTAs pass this so
25	  // signing in lands them on what they actually clicked instead of a generic
26	  // dashboard. Validated by `safeNext` — an unchecked `next` on a login form is an
27	  // open redirect and therefore a phishing primitive — so it is never trusted,
28	  // here or in the action.
29	  const { next, error } = await searchParams;
30	  const dest = safeNext(next ?? null);
31	  // Only ever surface a message from our own fixed map — never echo the raw
32	  // query value into the page.
33	  const googleError = error ? GOOGLE_ERRORS[error] : undefined;
34	
35	  // Already signed in? Then this page is just a waypoint: send them where they
36	  // were going. Without this, a public CTA written as `/login?next=/dashboard/x`
37	  // would strand EXISTING customers on a sign-in form they do not need — trading
38	  // one dead end for a worse one, since it asks a paying customer to authenticate
39	  // twice.
40	  const user = await currentUser();
41	  if (user) redirect(dest ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));
42	
43	  return (
44	    <AuthShell
45	      heading="Welcome back"
46	      sub="Sign in to manage your servers and billing."
47	      bullets={[
48	        "Instant NVMe VPS provisioning",
49	        "Real-time metrics and one-click reinstalls",
50	        "Full root access on every plan",
51	      ]}
52	    >
53	      {/* The VALIDATED destination, never the raw query value: a rejected
54	          `next` must not be echoed into the DOM at all. It could not cause a
55	          redirect (the action re-validates), but rendering attacker-supplied
56	          text into a form for no reason is how the next bug starts. */}
57	      <LoginForm next={dest ?? undefined} googleEnabled={googleOauthConfigured()} googleError={googleError} />
58	    </AuthShell>
59	  );
60	}
