import { redirect } from "next/navigation";
import { RegisterForm } from "@/components/AuthForms";
import { AuthShell } from "@/components/marketing/AuthShell";
import { ReferralCapture } from "@/components/customer/ReferralCapture";
import { currentUser } from "@/lib/auth";
import { safeNext } from "@/lib/safe-next";
import { googleOauthConfigured } from "@/lib/google-oauth";

/** Friendly copy for the `?error=` codes the Google OAuth routes bounce back. */
const GOOGLE_ERRORS: Record<string, string> = {
  google_unavailable: "Google sign-in isn't set up on this server yet. Use your email and password.",
  google_ratelimited: "Too many sign-in attempts. Please wait a moment and try again.",
  google_cancelled: "Google sign-in was cancelled.",
  google_state: "That Google sign-in link expired or didn't match. Please try again.",
  google_unverified: "Your Google email isn't verified, so we can't sign you in with it.",
  google_error: "Couldn't finish signing in with Google. Please try again.",
  account_suspended: "This account is suspended.",
};

export default async function RegisterPage({
  searchParams,
}: {
  searchParams: Promise<{ next?: string; error?: string }>;
}) {
  // Where the visitor was heading before hitting the sign-up wall. Carried
  // through the Google OAuth flow so first sign-in lands them where they meant to
  // go. Validated by `safeNext` — an unchecked `next` is an open redirect and
  // therefore a phishing primitive — so it is never trusted, here or in the action.
  const { next, error } = await searchParams;
  const dest = safeNext(next ?? null);
  // Only ever surface a message from our own fixed map — never echo the raw
  // query value into the page.
  const googleError = error ? GOOGLE_ERRORS[error] : undefined;

  // Already signed in? Then this page is a waypoint: send them onward instead of
  // asking a paying customer to authenticate again.
  const user = await currentUser();
  if (user) redirect(dest ?? (user.role === "ADMIN" ? "/admin" : "/dashboard"));

  return (
    <AuthShell
      heading="Create your account"
      sub="Deploy your first server in under a minute."
      // Two of these three were untrue. "No credit card required to get started"
      // implied a free first server — free deploys are admin-only, and a customer
      // with a $0 wallet gets "Insufficient balance. Top up your wallet first."
      // And "18+ OS images" was a hardcode the live catalogue passed long ago:
      // the homepage counts the same catalogue and renders 31+. A number nothing
      // computes goes stale by default, so this states the capability instead.
      bullets={[
        "Free to create — you pay when you deploy",
        "One-click OS images, control panels and apps",
        "Pay monthly, cancel anytime",
      ]}
    >
      <ReferralCapture />
      <RegisterForm next={dest ?? undefined} googleEnabled={googleOauthConfigured()} googleError={googleError} />
    </AuthShell>
  );
}
